def leggi_prova(testo):
    dati, scartate = [], 0
    righe = testo.strip().splitlines()[1:]
    for riga in righe:
        try:
            t_s, f_s = riga.split(";")
            t = float(t_s.replace(",", "."))
            F = float(f_s.replace(",", "."))
        except ValueError:
            scartate += 1
            continue
        if dati and t <= dati[-1][0]:
            scartate += 1
            continue
        dati.append((t, F))
    return dati, scartate
